bool solution(int T, int N, int arrive[], int arrive_len, int want[], int want_len) {
    int sold = 0;  // 지금까지 팔린 도넛 수
    for (int i = 0; i < arrive_len; i++) {
        int made = arrive[i] / T * N;  // arrive[i]분까지 만든 도넛 수
        if (made - sold < want[i])     // 남은 도넛이 원하는 개수보다 적으면 실패
            return false;
        sold += want[i];
    }
    return true;
}

