#include <stdbool.h>

bool solution(int T, int N, int L, int arrive[], int arrive_len) {
    int stock = 0;  // 진열대에 있는 와플 수
    int next = T;   // 다음에 와플을 굽는 시각
    for (int i = 0; i < arrive_len; i++) {
        while (next <= arrive[i]) {  // 손님이 오기 전(같은 시각 포함)에 구운 와플을 올림
            stock += N;
            if (stock > L)
                stock = L;
            next += T;
        }
        if (stock == 0)
            return false;
        stock--;
    }
    return true;
}

